head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정
    //  ※ windowContainer 는 내부 윈도우 영역(_window)이 absolute 로 배치되므로 컨테이너 자신이 positioned 여야 한다.
    //    (createBasicWindowContainer 도 style 에 position:relative 를 고정으로 포함) -> 기본 style 로 position:relative 를
    //    먼저 넣고, style(target) 조건값을 뒤에 붙여 조건이 선택되면 조건값이 우선 적용되도록 한다.
    let cStyle = "position:relative;";
    cStyle += scwin.gVar["cStyle"];
    cStyle += "width:500px; height:300px;"
    let cStyleParent = scwin.gVar["cStyleParent"];

    // parent 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp
    );

    // createBasicWindowContainer(고정 style) 대신 windowContainer 를 직접 생성 (parent1 하위, cStyle=con_style_target 반영 -> position 조건 확인)
    let strTarget = '';
    strTarget += '<w2:windowContainer ' + strNameSpace + ' style="' + cStyle + '">';
    strTarget += '<w2:windowToolbar>';
    strTarget += '<w2:controlIconLayer>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '</w2:controlIconLayer>';
    strTarget += '<w2:nameLayer></w2:nameLayer>';
    strTarget += '<w2:selectedNameLayer></w2:selectedNameLayer>';
    strTarget += '</w2:windowToolbar>';
    strTarget += '</w2:windowContainer>';

    // base(common_M)가 objParent.target1 로 접근하므로 target1 id 로 생성 (parent1 하위에 생성)
    scwin.target1 = await $p.dynamicCreate('target1', "windowContainer", strTarget, parent1);

    // 내용 확인용 윈도우 생성
    scwin.target1.createWindow({
        title : "windowContainer_link_1",
        src : "/sample/common_link/windowContainer_link_1.xml",
        windowTitle : "TEST",
        windowId : "test001",
        openAction : "selectWindow"
    });
}
